func TestMoveAcrossDevicesWithReadOnlyDirectories(t *testing.T) {
	if os.Geteuid() == 0 {
		t.Skip("root ignores directory permissions")
	}
	simulateCrossDevice(t)
	src, dst := t.TempDir(), t.TempDir()
